        int complete = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            queue<int> q;
            vector<int> component;

            q.push(i);
            visited[i] = true;

            while (!q.empty()) {
                int node = q.front();
                q.pop();
                component.push_back(node);

                for (int next : graph[node]) {
                    if (!visited[next]) {
                        visited[next] = true;
                        q.push(next);
                    }
                }
            }

            int size = component.size();
            boolean ok = true;

            for (int node : component) {
                if ((int)graph[node].size() != size - 1) {
                    ok = false;
                    break;
                }
            }

            if (ok) complete++;
        }

        return complete;
    }
